import{_ as e,o as a,c as l,a0 as r}from"./chunks/framework.DqMqoJl9.js";const x=JSON.parse('{"title":"展开链讲稿 · 第二分册：统一体怎么自组装，α 从哪里来","description":"","frontmatter":{},"headers":[],"relativePath":"L002_第二分册_统一体自组装与α.md","filePath":"L002_第二分册_统一体自组装与α.md"}'),d={name:"L002_第二分册_统一体自组装与α.md"};function n(o,t,s,i,$,g){return a(),l("div",null,[...t[0]||(t[0]=[r('<div><h1 id="展开链讲稿-·-第二分册-统一体怎么自组装-α-从哪里来" tabindex="-1">展开链讲稿 · 第二分册：统一体怎么自组装，α 从哪里来 <a class="header-anchor" href="#展开链讲稿-·-第二分册-统一体怎么自组装-α-从哪里来" aria-label="Permalink to &quot;展开链讲稿 · 第二分册：统一体怎么自组装，α 从哪里来&quot;">​</a></h1><blockquote><p><strong>稿子性质</strong>：本稿是<strong>撰写</strong>，不是摘录。它接续第一分册（最小内核），回答链条上紧接着的两个问题： 那个内核怎么长出一个<strong>统一群</strong>，以及常数 $\\alpha$ 在这条链上处在什么位置。</p><p><strong>它不是权威源</strong>。权威源仍是各文档原文与根 <code>README.md</code>；本稿的每一条论断都在<strong>附录 A</strong> 里钉到出处。</p><p><strong>三条写作纪律</strong>（本稿对 <code>AGENTS.md</code> 三条红线的具体执行）：</p><ol><li><strong>不欺骗</strong>——未证处不得写成已证。本稿凡涉及未闭合处，一律写明缺口编号与状态。</li><li><strong>不绕过</strong>——缺口不省略、不用&quot;因此&quot;跨过；必须跨时，句式是&quot;在缺口 X 未闭合的前提下，下游成立的是……&quot;。</li><li><strong>不虚构</strong>——只用原文已有的概念、术语、数值与关系；不引入原文未涉及的观点，也不替原文补理由（原文未展开动机处，本稿明写&quot;原文未在此处展开&quot;）。</li></ol></blockquote><hr><h2 id="卷首-·-本分册在链条上的位置" tabindex="-1">卷首 · 本分册在链条上的位置 <a class="header-anchor" href="#卷首-·-本分册在链条上的位置" aria-label="Permalink to &quot;卷首 · 本分册在链条上的位置&quot;">​</a></h2><p>第一分册把内核交代完：一个共轭对的替换、一个由 Sprinkling 逼出的测度、一个从 $\\xi$ 算出的作用量量子。但内核本身只是舞台与语法——<strong>它还没说出任何一个具体的规范群</strong>。</p><p>本分册要做的事，就是把这套语法用到&quot;禁闭边界&quot;这个具体位置上：先看离散自由度怎么被自组织成一个 4-单纯形（第一章），再看这个单纯形的一个矩阵怎么读出三个数（第二章），然后交代这三个数凭什么被说成&quot;三种规范耦合的相对强度&quot;，以及由此牵出的<strong>整个框架里最密的一片断点</strong>（第三章）。最后两章处理两个常数的地位——$\\alpha$（第四章）与 $G_N$（第五章）；它们的严格性完全不同，混在一起写就会失真。</p><table tabindex="0"><thead><tr><th style="text-align:left;">层</th><th style="text-align:left;">省略什么</th><th style="text-align:left;">回答什么</th><th style="text-align:left;">在哪节</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>导读层</strong></td><td style="text-align:left;">省略全部构造细节</td><td style="text-align:left;">统一体是&quot;装&quot;出来的，还是一个签名带出七个关联</td><td style="text-align:left;">第一章前半</td></tr><tr><td style="text-align:left;"><strong>概念层</strong></td><td style="text-align:left;">省略证明，保留对象与谱</td><td style="text-align:left;">4-单纯形、边-面关联矩阵、本征值三重身份</td><td style="text-align:left;">第一、二章后半</td></tr><tr><td style="text-align:left;"><strong>链条层</strong></td><td style="text-align:left;">不省略顺序，标注状态与断点</td><td style="text-align:left;">从组装到规范群，缺口在哪里</td><td style="text-align:left;">第三、四、五章</td></tr><tr><td style="text-align:left;"><strong>技术层</strong></td><td style="text-align:left;">不省略任何东西</td><td style="text-align:left;">嘉当方程、连续极限、公式与参数</td><td style="text-align:left;">指向原文 §7.3–§7.5</td></tr></tbody></table><hr><h2 id="第一章-组装-从离散自组织到-4-单纯形" tabindex="-1">第一章 组装：从离散自组织到 4-单纯形 <a class="header-anchor" href="#第一章-组装-从离散自组织到-4-单纯形" aria-label="Permalink to &quot;第一章 组装：从离散自组织到 4-单纯形&quot;">​</a></h2><h3 id="_1-1-一条五步的组装链" tabindex="-1">1.1 一条五步的组装链 <a class="header-anchor" href="#_1-1-一条五步的组装链" aria-label="Permalink to &quot;1.1 一条五步的组装链&quot;">​</a></h3><p>原文把&quot;禁闭内部的离散自由度&quot;到&quot;规范群&quot;的路径写成一条链：</p><p>$$\\text{禁闭内部离散自由度（因果集事件）} \\xrightarrow{\\text{前核子自组织 + 粗粒化}} \\text{禁闭边界组合结构（4-单纯形）} \\xrightarrow{\\text{边-面关联}} M=E^TE \\xrightarrow{\\text{本征值分析}} {9,4,1} \\xrightarrow{S_5\\text{表示论}} \\text{SU(5) 规范群结构}$$</p><p>注意第二步的措辞：<strong>前核子自组织 + 粗粒化</strong>。禁闭边界不是外加的边界条件，而是前核子自组织的结果——这与第一分册第五章&quot;禁闭不是 QCD 动力学的结果&quot;是同一件事的不同侧面。【锚 A-21】</p><h3 id="_1-2-一个容易读错的地方-这个单纯形不是-a-4-根系的-weyl-室" tabindex="-1">1.2 一个容易读错的地方：这个单纯形不是 $A_4$ 根系的 Weyl 室 <a class="header-anchor" href="#_1-2-一个容易读错的地方-这个单纯形不是-a-4-根系的-weyl-室" aria-label="Permalink to &quot;1.2 一个容易读错的地方：这个单纯形不是 $A_4$ 根系的 Weyl 室&quot;">​</a></h3><p>原文专门澄清了一次，因为这里极易混：CQM 的 4-单纯形<strong>不是</strong> $A_4$ 根系的 Weyl 室——$A_4$ 的 Weyl 室不是正单纯形，因为 Dynkin 图是链状，单根夹角有 120° 和 90°。</p><p>正四单纯形出现在 <strong>SU(5) 基础表示 $\\mathbf 5$ 的权空间</strong>里：5 个权向量 $\\nu_1,\\dots,\\nu_5$ 满足 $\\sum_i\\nu_i=0$ 且两两内积相等，恰好构成正四单纯形的 5 个顶点；其对称群正是 $A_4$ 的 Weyl 群 $S_5$。</p><p>这个区分不是修辞上的洁癖：它决定了后面&quot;${9,4,1}$ 从哪来&quot;的全部推导方式。【锚 A-22】</p><h3 id="_1-3-面元账本" tabindex="-1">1.3 面元账本 <a class="header-anchor" href="#_1-3-面元账本" aria-label="Permalink to &quot;1.3 面元账本&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">面元</th><th style="text-align:center;">数量</th></tr></thead><tbody><tr><td style="text-align:left;">0-面（顶点）</td><td style="text-align:center;">5</td></tr><tr><td style="text-align:left;">1-面（边）</td><td style="text-align:center;">10</td></tr><tr><td style="text-align:left;">2-面（三角形）</td><td style="text-align:center;">10</td></tr><tr><td style="text-align:left;">3-面（四面体）</td><td style="text-align:center;">5</td></tr><tr><td style="text-align:left;">4-面</td><td style="text-align:center;">1</td></tr></tbody></table><p>总面元数 $31=2^5-1$。这个数后面还会回来：$\\kappa=(31+☯)/30$ 里的 31 就是它（第五章）。【锚 A-23】</p><hr><h2 id="第二章-谱-一个矩阵读出三个数" tabindex="-1">第二章 谱：一个矩阵读出三个数 <a class="header-anchor" href="#第二章-谱-一个矩阵读出三个数" aria-label="Permalink to &quot;第二章 谱：一个矩阵读出三个数&quot;">​</a></h2><h3 id="_2-1-对象" tabindex="-1">2.1 对象 <a class="header-anchor" href="#_2-1-对象" aria-label="Permalink to &quot;2.1 对象&quot;">​</a></h3><p>边-面关联矩阵 $M=E^TE\\in\\mathbb R^{10\\times 10}$，本征值 ${9,4,1}$，重数 ${1,4,5}$。【锚 A-24】</p><h3 id="_2-2-五步证明" tabindex="-1">2.2 五步证明 <a class="header-anchor" href="#_2-2-五步证明" aria-label="Permalink to &quot;2.2 五步证明&quot;">​</a></h3><p>原文给出的证明是干净的表示论路子，逐步如下：</p><ol><li>$M$ 与 $S_5$ 对易（组合结构在顶点置换下不变）；</li><li>由 Schur 引理，本征空间必须是 $S_5$ 的不可约表示；</li><li>10 维边空间分解：$\\mathbf{10}=\\mathbf 1\\oplus\\mathbf 4\\oplus\\mathbf 5$；</li><li>均匀向量 $\\mathbf u=(1,\\dots,1)^T/\\sqrt{10}$ 给出 $\\lambda_1=9$；</li><li>迹条件 $\\operatorname{Tr}(M)=30$ 与 $\\operatorname{Tr}(M^2)=150$ 解出 $\\lambda_4=4$、$\\lambda_5=1$。</li></ol><p>原文另附数值验证：$\\lambda(M)_{\\text{numerical}}={9.000000,,4.000000\\times4,,1.000000\\times5}$。【锚 A-24】</p><h3 id="_2-3-三个本征空间对三个扇区" tabindex="-1">2.3 三个本征空间对三个扇区 <a class="header-anchor" href="#_2-3-三个本征空间对三个扇区" aria-label="Permalink to &quot;2.3 三个本征空间对三个扇区&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">本征空间</th><th style="text-align:center;">本征值</th><th style="text-align:center;">维数</th><th style="text-align:left;">$S_5$ 表示</th><th style="text-align:left;">物理扇区</th></tr></thead><tbody><tr><td style="text-align:left;">$V_1$</td><td style="text-align:center;">9</td><td style="text-align:center;">1</td><td style="text-align:left;">$\\mathbf 1$</td><td style="text-align:left;">SU(3) 色</td></tr><tr><td style="text-align:left;">$V_4$</td><td style="text-align:center;">4</td><td style="text-align:center;">4</td><td style="text-align:left;">$\\mathbf 4$</td><td style="text-align:left;">SU(2) 弱</td></tr><tr><td style="text-align:left;">$V_5$</td><td style="text-align:center;">1</td><td style="text-align:center;">5</td><td style="text-align:left;">$\\mathbf 5$</td><td style="text-align:left;">U(1) 电磁</td></tr></tbody></table><p>原文对这一表的结论写得很短，但它是本章的要害：<strong>$S_5$ 是 SU(5) 的 Weyl 群，本征值比例 $9:4:1$ 直接决定三种规范耦合的相对强度。</strong>【锚 A-24】</p><p>读到这里要停一下：这张表给出的是<strong>相对强度</strong>，不是绝对数值。从&quot;相对&quot;走到&quot;绝对&quot;（也就是走到 $\\alpha$），中间还隔着一整套重组实现——那是第四章的事。</p><hr><h2 id="第三章-一个签名-七个关联-本分册断点最密的一章" tabindex="-1">第三章 一个签名，七个关联（本分册断点最密的一章） <a class="header-anchor" href="#第三章-一个签名-七个关联-本分册断点最密的一章" aria-label="Permalink to &quot;第三章 一个签名，七个关联（本分册断点最密的一章）&quot;">​</a></h2><h3 id="_3-1-一证七联" tabindex="-1">3.1 一证七联 <a class="header-anchor" href="#_3-1-一证七联" aria-label="Permalink to &quot;3.1 一证七联&quot;">​</a></h3><p>原文用一个框架把这一章的野心与风险同时交代清楚：</p><blockquote><p><strong>核心定理（未证明）</strong>：前核子自组织在禁闭边界的稳态是正四单纯形，代数签名 $A_4=\\text{Cartan}(\\text{SU}(5))$。此定理一旦证明，七大关联全部自动涌出——$☯$ 三重锁定、正四单纯形三重对应、SU(5) = 大统一群、双曲度规与黎曼零点谱、维度匹配、真空涨落隔离、精细结构常数 $\\alpha^{-1}$。</p></blockquote><p>原文对&quot;七大关联&quot;的定性很重要：它们是<strong>同一对象 $A_4$ 在七个物理维度上的延伸，而非七个独立巧合</strong>。【锚 A-25】</p><h3 id="_3-2-断点在这里-不在别处" tabindex="-1">3.2 断点在这里，不在别处 <a class="header-anchor" href="#_3-2-断点在这里-不在别处" aria-label="Permalink to &quot;3.2 断点在这里，不在别处&quot;">​</a></h3><blockquote><p><strong>断点（就地标出）</strong>：上述核心定理<strong>未证明</strong>，对应<strong>缺口 C（未闭合）</strong>，原文在缺口台账中将其记为&quot;严谨性最大敞口&quot;。因此本分册第三、四、五章的全部内容，都应以&quot;C 未闭合&quot;为前提来读：一旦 C 未闭合，&quot;$A_4=\\text{Cartan}(\\text{SU}(5))$&quot;就还是一个<strong>目标</strong>，而不是一条<strong>已成立的同一性</strong>。【锚 A-26】</p></blockquote><h3 id="_3-3-嘉当矩阵的三重身份" tabindex="-1">3.3 嘉当矩阵的三重身份 <a class="header-anchor" href="#_3-3-嘉当矩阵的三重身份" aria-label="Permalink to &quot;3.3 嘉当矩阵的三重身份&quot;">​</a></h3><p>原文列出三重身份：①离散哈密顿量 $H_{\\text{disc}}=A_4/a^2$；②离散能动张量 $T^{00}=H_{\\text{disc}}$；③根系几何——$A_4$ 的根系 = 4-单纯形骨架（在权空间意义下）。</p><p>紧接着是一句必须连着念的限定：<strong>三重同一性严格成立，条件于 §7.1 核心定理——未证明</strong>；且此同一性仅在退相干完成后成立，是禁闭边界上非交换代数粗粒化为交换几何的结果。【锚 A-27】</p><h3 id="_3-4-嘉当方程与它的连续极限" tabindex="-1">3.4 嘉当方程与它的连续极限 <a class="header-anchor" href="#_3-4-嘉当方程与它的连续极限" aria-label="Permalink to &quot;3.4 嘉当方程与它的连续极限&quot;">​</a></h3><p>禁闭边界离散动力学取 Cayley 型离散化：</p><p>$$\\left(I+\\frac{ivA_4}{2a}\\right)\\psi^{n+1}=\\left(I-\\frac{ivA_4}{2a}\\right)\\psi^n$$</p><p>其中 $a$ 为格点间距（无量纲）、$v$ 为特征速度（因果时与坐标时的实现标度）、$\\psi^n\\in\\mathbb C^4$ 为第 $n$ 个再生产步骤的态矢量，时间步进 $\\Delta\\tau=a/v$。原文强调：幺正性 $U^\\dagger U=I$ <strong>严格成立</strong>（Cayley 型）。连续极限为 $A_4/a^2\\to-\\partial_u^2+\\partial_u$（Taylor 展开 + 加权内积分部积分）；嘉当特征值 $\\lambda_k=2-2\\cos(k\\pi/5)$ 是大统一能标下的耦谱。【锚 A-28】</p><blockquote><p><strong>定位声明（原文原文）</strong>：SU(5) 嘉当矩阵 $A_4$ 是禁闭边界退相干后的<strong>涌现结构</strong>。禁闭内部为非交换几何，其动力学由非交换代数（而非交换的 $A_4$）描述。嘉当方程<strong>仅在禁闭边界／退相干后的语境下成立</strong>。</p></blockquote><p>这句话限定了本章全部方程的使用范围：它们不是&quot;普适动力学&quot;，而是&quot;边界语境下的动力学&quot;。【锚 A-28】</p><hr><h2 id="第四章-alpha-它的地位比数字本身重要" tabindex="-1">第四章 $\\alpha$：它的地位比数字本身重要 <a class="header-anchor" href="#第四章-alpha-它的地位比数字本身重要" aria-label="Permalink to &quot;第四章 $\\alpha$：它的地位比数字本身重要&quot;">​</a></h2><h3 id="_4-1-链条的位置" tabindex="-1">4.1 链条的位置 <a class="header-anchor" href="#_4-1-链条的位置" aria-label="Permalink to &quot;4.1 链条的位置&quot;">​</a></h3><p>$$\\text{SU}(5)\\xRightarrow{\\text{重组实现}}U(1)\\text{电磁群}\\xrightarrow{\\text{耦合常数}}\\alpha$$</p><p>原文对这一路径的表述是：$\\alpha$ 来自 SU(5) 重组实现后 $U(1)$ 电磁群的耦合常数，$\\alpha^{-1}=16384\\pi/375$ 是 GL(5) 固定层级整体的反映。【锚 A-29】</p><h3 id="_4-2-这个数字的成色" tabindex="-1">4.2 这个数字的成色 <a class="header-anchor" href="#_4-2-这个数字的成色" aria-label="Permalink to &quot;4.2 这个数字的成色&quot;">​</a></h3><p>$\\alpha^{-1}=16384\\pi/375\\approx137.2583$；与实验值 $137.035999$（CODATA 2022）偏差约 $0.162%$（≈1622 ppm）。</p><p>原文对它的定位需要整段保留，删掉任何一半都会改变性质：<strong>一阶近似、待高阶修正</strong>；&quot;这不是到 ppm 的精确符合，故<strong>不能称&#39;严格/精确&#39;</strong>，数值尚未收敛为唯一精确值&quot;；标准模型中 $\\alpha$ 是需精密测量的输入参数，并无被主流接受的纯数论推导；此处为 CQM 框架内的<strong>启发式构造匹配</strong>。【锚 A-29】</p><h3 id="_4-3-双口径并列" tabindex="-1">4.3 双口径并列 <a class="header-anchor" href="#_4-3-双口径并列" aria-label="Permalink to &quot;4.3 双口径并列&quot;">​</a></h3><p>原文还登记了另一条口径：Wyler 常数 $\\alpha^{-1}_{\\text{Wyler}}=\\frac{16}{9}\\pi^{11/4}(5!)^{1/4}\\approx137.0361$（偏差 $0.61$ ppm），由 $A_4$ 全部群论不变量（$h=5$、$r=4$、$|W|=120$、$\\text{tr}=8$）给出。</p><p>两条口径的关系，原文写明：$16384\\pi/375$ 为启发式近似，Wyler 式为 $A_4$ 群论不变量的组合；两者偏差（ppm）之比约 $2659$，<strong>此为相对精度之比，不构成独立精度证据</strong>。【锚 A-29】</p><p>本稿不做的一件事：不替原文在两条口径之间选边。并列登记是原文的写法。</p><h3 id="_4-4-常数分类-alpha-与量纲的关系" tabindex="-1">4.4 常数分类：$\\alpha$ 与量纲的关系 <a class="header-anchor" href="#_4-4-常数分类-alpha-与量纲的关系" aria-label="Permalink to &quot;4.4 常数分类：$\\alpha$ 与量纲的关系&quot;">​</a></h3><p>原文给 $\\alpha$ 的归类是&quot;<strong>比值型无量纲常数</strong>&quot;——它的&quot;无量纲&quot;来自<strong>量纲相消</strong>（$[\\text{能量}\\cdot\\text{长度}]$ 相消），因此它与量纲<strong>紧密相关</strong>，是量纲内差异的定量体现，<strong>不是</strong>&quot;与量纲无关&quot;。【锚 A-29】</p><p>这一条与第一分册第四章&quot;每压掉一个量纲冒出一个特征常数&quot;是同一条原则的两面：无量纲不等于脱离量纲。</p><hr><h2 id="第五章-顺带说清-g-n-在同一张表上的位置" tabindex="-1">第五章 顺带说清 $G_N$ 在同一张表上的位置 <a class="header-anchor" href="#第五章-顺带说清-g-n-在同一张表上的位置" aria-label="Permalink to &quot;第五章 顺带说清 $G_N$ 在同一张表上的位置&quot;">​</a></h2><p>$G_N$ 之所以要在这里提一句，是因为它和 $\\alpha$ 出现在同一批段落里，而成色完全不同；把两者混着写，是本分册最想避免的失真。</p><h3 id="_5-1-输入与公式" tabindex="-1">5.1 输入与公式 <a class="header-anchor" href="#_5-1-输入与公式" aria-label="Permalink to &quot;5.1 输入与公式&quot;">​</a></h3><p>参数表（逐字取自原文）：</p><table tabindex="0"><thead><tr><th style="text-align:center;">符号</th><th style="text-align:center;">数值</th><th style="text-align:left;">来源</th></tr></thead><tbody><tr><td style="text-align:center;">$I$</td><td style="text-align:center;">$5/3$</td><td style="text-align:left;">SU(5) Dynkin 指数比 $T(\\mathbf{24})/T(\\mathbf 8)$</td></tr><tr><td style="text-align:center;">$\\lambda_c$</td><td style="text-align:center;">$1.3160229113077\\ldots$</td><td style="text-align:left;">Mathieu 方程临界参数</td></tr><tr><td style="text-align:center;">$☯$</td><td style="text-align:center;">$0.023095708966\\ldots$</td><td style="text-align:left;">相变量子</td></tr><tr><td style="text-align:center;">$\\mathfrak c_1$</td><td style="text-align:center;">$200.040454832\\ldots$</td><td style="text-align:left;">第一耦级 $1/4+\\gamma_1^2$</td></tr><tr><td style="text-align:center;">$\\kappa$</td><td style="text-align:center;">$1.034103190\\ldots$</td><td style="text-align:left;">4-单纯形/Adele 周期修正 $\\kappa=(31+☯)/30$</td></tr><tr><td style="text-align:center;">$m_p$</td><td style="text-align:center;">$0.9382720882$ GeV</td><td style="text-align:left;"><strong>唯一量纲输入</strong>（量纲锚点，PDG 2022）</td></tr></tbody></table><p>其中 $\\kappa$ 的含义原文交代得很具体：$\\kappa=(N_{\\text{faces}}+☯)/N_{\\text{cycle}}$，$N_{\\text{faces}}=31=2^5-1$ 是 4-单纯形非空面元数（整数组合不变量），$N_{\\text{cycle}}=30=2\\cdot3\\cdot5$ 是素数周期条件；$+☯$ 项反映从离散因果集到连续几何过渡中组合不变量与谱不变量的统一。原文并说明：该公式的其余输入为选定的组合-谱不变量，<strong>未拟合 $G_N$</strong>。</p><p>公式：</p><p>$$G_N=\\frac{\\hbar c}{m_p^2}\\cdot I\\cdot\\lambda_c\\cdot☯^2\\cdot\\mathfrak c_1\\cdot\\exp!\\left(-\\frac{2}{☯}\\right)\\cdot(1+\\kappa☯)$$</p><p>结果 $G_N=6.6742810045\\times10^{-11}\\ \\mathrm{m^3,kg^{-1},s^{-2}}$（SI），与 CODATA 2022 偏差约 $-3$ ppm。【锚 A-30】</p><h3 id="_5-2-这个数字的成色-与-alpha-完全不同" tabindex="-1">5.2 这个数字的成色：与 $\\alpha$ 完全不同 <a class="header-anchor" href="#_5-2-这个数字的成色-与-alpha-完全不同" aria-label="Permalink to &quot;5.2 这个数字的成色：与 $\\alpha$ 完全不同&quot;">​</a></h3><p>原文对 $-3$ ppm 的限定，必须连着念：</p><blockquote><p>该量由所选不变量固定计算、无对 $G_N$ 的拟合自由度；但因公式结构源于启发式选择，且<strong>历史上此类&quot;无参数闭合公式&quot;多次被证伪</strong>，故应视作<strong>待独立复现的构造性数字符合，而非被学界公认的独立预言</strong>。$\\alpha$、$G_N$ 在标准物理中仍是实验参数/基本输入。</p></blockquote><p>也就是说：$-3$ ppm 这个吻合度本身，<strong>不构成</strong>&quot;该公式正确&quot;的证据。可检验的点在别处——数值本身能否被第三方复现。【锚 A-30】</p><h3 id="_5-3-框架内-g-n-为什么由-su-5-几何给定" tabindex="-1">5.3 框架内 $G_N$ 为什么由 SU(5) 几何给定 <a class="header-anchor" href="#_5-3-框架内-g-n-为什么由-su-5-几何给定" aria-label="Permalink to &quot;5.3 框架内 $G_N$ 为什么由 SU(5) 几何给定&quot;">​</a></h3><p>原文给的理由是一条排除法：有效曲率必须同时满足<strong>交换几何</strong>（经典可对易）、<strong>长程</strong>（不被质量或禁闭屏蔽）、<strong>稳定</strong>（不随时间衰减）三个条件。禁闭内部为非交换几何，不提供经典曲率；$U(1)$ 是 Abel 群，没有非平凡的嘉当矩阵；弱力的几何贡献被 $S_5$ 对称性严格压制。SU(5) 位于禁闭边界——&quot;非交换 ↔ 交换&quot;过渡的临界点，三种规范群的面元通过同一个边-面关联矩阵 $E$ 耦合，产生同一个 Cartan 曲率算符 $M=E^TE$。【锚 A-30】</p><h3 id="_5-4-三条-不-以及一句自我限定" tabindex="-1">5.4 三条&quot;不&quot;，以及一句自我限定 <a class="header-anchor" href="#_5-4-三条-不-以及一句自我限定" aria-label="Permalink to &quot;5.4 三条&quot;不&quot;，以及一句自我限定&quot;">​</a></h3><p>原文列出：$G_N$ 不随能标跑动（区别于渐近安全量子引力）、不随时间演化（区别于 Brans–Dicke）、不随位置变化。实验条件（月球激光测距、脉冲双星、BBN、CMB）将 $G_N$ 的变率限制在 $&lt;10^{-12}$/年。</p><p>但原文紧接着补了一句本稿必须照抄的自我限定：这些&quot;不变性&quot;是标准引力学本就共享的 $G_N$ 常数性，<strong>并非 CQM 独有的可区分预言</strong>——真正的可检验点是 $G_N$ 的数值本身能否第三方复现，而非其常/不变性。【锚 A-30】</p><h3 id="_5-5-常数分类-g-n-是另一类" tabindex="-1">5.5 常数分类：$G_N$ 是另一类 <a class="header-anchor" href="#_5-5-常数分类-g-n-是另一类" aria-label="Permalink to &quot;5.5 常数分类：$G_N$ 是另一类&quot;">​</a></h3><p>原文把 $G_N$ 归为<strong>有量纲特征常数</strong>（$K_M=G_N^{-1}$），属&quot;<strong>跨量纲对</strong>&quot;；本节公式的其余输入（$I$、$\\lambda_c$、$☯$、$\\mathfrak c_1$、$\\kappa$）均为<strong>纯数型</strong>（组合/谱量，量纲发生学中无对应&quot;量纲对&quot;）；$m_e/m_p$ 则为<strong>比值型</strong>（同量纲对）。【锚 A-30】</p><p>至此本分册把两个常数的位置分开放好了：$\\alpha$ 是<strong>比值型</strong>、相对强度链条的末端、一阶近似；$G_N$ 是<strong>有量纲特征常数</strong>、无量纲组合通过量纲锚点 $m_p$ 恢复量纲、构造后验待独立复现。</p><hr><h2 id="附录-a-·-锚点表" tabindex="-1">附录 A · 锚点表 <a class="header-anchor" href="#附录-a-·-锚点表" aria-label="Permalink to &quot;附录 A · 锚点表&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">锚</th><th style="text-align:left;">论断摘要</th><th style="text-align:left;">出处</th><th style="text-align:left;">定位</th><th style="text-align:left;">核对状态</th></tr></thead><tbody><tr><td style="text-align:left;">A-21</td><td style="text-align:left;">五步组装链（前核子自组织 + 粗粒化）</td><td style="text-align:left;"><code>01 核心理论/CQM_核心_集成理论.md</code></td><td style="text-align:left;">§7.1</td><td style="text-align:left;">逐字核对</td></tr><tr><td style="text-align:left;">A-22</td><td style="text-align:left;">4-单纯形不是 $A_4$ 根系 Weyl 室；正四单纯形在 $\\mathbf 5$ 权空间；对称群 $S_5$</td><td style="text-align:left;">同上</td><td style="text-align:left;">§7.1</td><td style="text-align:left;">逐字核对</td></tr><tr><td style="text-align:left;">A-23</td><td style="text-align:left;">面元表与总数 $31=2^5-1$</td><td style="text-align:left;">同上</td><td style="text-align:left;">§7.1</td><td style="text-align:left;">逐字核对</td></tr><tr><td style="text-align:left;">A-24</td><td style="text-align:left;">$M=E^TE$、${9,4,1}$ 与重数、五步证明、数值验证、本征空间-扇区表、$9:4:1$</td><td style="text-align:left;">同上</td><td style="text-align:left;">§7.2</td><td style="text-align:left;">逐字核对</td></tr><tr><td style="text-align:left;">A-25</td><td style="text-align:left;">一证七联：核心定理（未证明）与七大关联</td><td style="text-align:left;">同上</td><td style="text-align:left;">§7.1 一证七联注</td><td style="text-align:left;">逐字核对</td></tr><tr><td style="text-align:left;">A-26</td><td style="text-align:left;">缺口 C 未闭合、严谨性最大敞口</td><td style="text-align:left;"><code>一体化研究/附录/缺口台账.md</code></td><td style="text-align:left;">§一、§二</td><td style="text-align:left;">逐字核对</td></tr><tr><td style="text-align:left;">A-27</td><td style="text-align:left;">嘉当矩阵三重身份与&quot;条件于 §7.1 核心定理&quot;</td><td style="text-align:left;"><code>01 核心理论/CQM_核心_集成理论.md</code></td><td style="text-align:left;">§7.3</td><td style="text-align:left;">逐字核对</td></tr><tr><td style="text-align:left;">A-28</td><td style="text-align:left;">嘉当方程、幺正性、连续极限、$\\lambda_k=2-2\\cos(k\\pi/5)$、涌现结构定位声明</td><td style="text-align:left;">同上</td><td style="text-align:left;">§7.3</td><td style="text-align:left;">逐字核对</td></tr><tr><td style="text-align:left;">A-29</td><td style="text-align:left;">$\\alpha$ 路径、$16384\\pi/375$、0.162%、一阶近似、Wyler 双口径、常数分类</td><td style="text-align:left;">同上</td><td style="text-align:left;">§7.4</td><td style="text-align:left;">逐字核对</td></tr><tr><td style="text-align:left;">A-30</td><td style="text-align:left;">$G_N$ 参数表与公式、$-3$ ppm 及其限定、SU(5) 几何理由、三条&quot;不&quot;与自我限定、常数分类</td><td style="text-align:left;">同上</td><td style="text-align:left;">§7.5</td><td style="text-align:left;">逐字核对</td></tr></tbody></table><h2 id="附录-b-·-六关自检-本稿口径" tabindex="-1">附录 B · 六关自检（本稿口径） <a class="header-anchor" href="#附录-b-·-六关自检-本稿口径" aria-label="Permalink to &quot;附录 B · 六关自检（本稿口径）&quot;">​</a></h2><p>沿用第一分册附录 B 的六关：出处存在／对象正确／段落相关／论断被支撑／<strong>限定语保留</strong>／来源适配。本分册的限定语集中在三处，写作时逐处核对：$\\alpha$ 的&quot;一阶近似、不能称严格/精确&quot;、两条口径的&quot;比值不构成独立精度证据&quot;、$G_N$ 的&quot;构造性数字符合、非公认独立预言&quot;。</p><h2 id="附录-c-·-下一分册" tabindex="-1">附录 C · 下一分册 <a class="header-anchor" href="#附录-c-·-下一分册" aria-label="Permalink to &quot;附录 C · 下一分册&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">分册</th><th style="text-align:left;">覆盖链条段</th><th style="text-align:left;">主要依据</th></tr></thead><tbody><tr><td style="text-align:left;">第三分册</td><td style="text-align:left;">谱方程与黎曼零点（Sierra-CQM 耦谱定理）</td><td style="text-align:left;"><code>集成理论</code> 第八部分</td></tr><tr><td style="text-align:left;">第四分册</td><td style="text-align:left;">超导涌现链（跃迁耦级谱、自由能竞争与 $T_c$），含 G9–G22 断点</td><td style="text-align:left;"><code>集成理论</code> 第十一部分</td></tr><tr><td style="text-align:left;">第五分册</td><td style="text-align:left;">与标准理论的关系、纤维丛结构与涨落伴丛</td><td style="text-align:left;"><code>集成理论</code> 第十二、十三部分</td></tr><tr><td style="text-align:left;">第六分册</td><td style="text-align:left;">量纲发生学专章（$K$ 家族逐项、自守形式猜想）</td><td style="text-align:left;"><code>量纲与群论</code> §六、§七</td></tr></tbody></table></div>',1)])])}const p=e(d,[["render",n]]);export{x as __pageData,p as default};
